// Coast Commons (/coast-commons/): static pages under public/coast-commons/ generated by
// scripts/coast-commons/build.mjs. These checks keep the JSON twin, the pages, the manifests and
// the area's content rules in step.
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = new URL('../', import.meta.url);
const read = (p) => readFileSync(new URL(p, root), 'utf8');
const twin = JSON.parse(read('public/coast-commons.json'));
const hub = read('public/coast-commons/index.html');
const page = (slug) => read(`public/coast-commons/${slug}/index.html`);
const slugs = twin.towns.map((t) => t.slug);
const all = ['', 'pattern', ...slugs];
const html = (slug) => (slug ? page(slug) : hub);

test('the committed pages match the generator', () => {
  execFileSync(process.execPath, [fileURLToPath(new URL('scripts/coast-commons/build.mjs', root)), '--check'], { stdio: 'pipe' });
});

test('fifteen towns, each within 25 miles, each a file, El Segundo the one flagship', () => {
  assert.equal(twin.towns.length, 15);
  for (const t of twin.towns) {
    assert.ok(existsSync(new URL(`public/coast-commons/${t.slug}/index.html`, root)), t.slug);
    assert.equal(t.url, `https://pointcast.xyz/coast-commons/${t.slug}/`);
    assert.ok(t.miles_from_el_segundo >= 0 && t.miles_from_el_segundo <= 25, `${t.slug} ${t.miles_from_el_segundo}`);
    assert.equal(t.verified, '2026-11-11');
    assert.ok(t.governing_body);
  }
  assert.deepEqual(twin.towns.filter((t) => t.flagship).map((t) => t.slug), ['el-segundo']);
  assert.equal(twin.towns.find((t) => t.flagship).miles_from_el_segundo, 0);
  assert.match(twin.method.distance, /Straight-line/);
});

test('every rule entry is either sourced and dated or says Not verified with no link', () => {
  for (const t of twin.towns) {
    for (const [k, r] of [...Object.entries(t.rules), ...t.character.map((c, i) => [`character ${i}`, c])]) {
      if (r.verified) {
        assert.ok(r.sources.length >= 1, `${t.slug} ${k} has a source`);
        for (const s of r.sources) { assert.match(s.url, /^https:\/\//); assert.equal(s.opened, '2026-11-11'); }
      } else {
        assert.match(r.summary, /^Not verified\./, `${t.slug} ${k}`);
        assert.equal(r.sources.length, 0, `${t.slug} ${k} carries no link`);
      }
    }
    const p = page(t.slug);
    for (const r of Object.values(t.rules)) for (const s of r.sources) assert.ok(p.includes(`href="${s.url.replace(/&/g, '&amp;')}"`), `${t.slug} links ${s.url}`);
    assert.match(p, /read on <time datetime="2026-11-11">|opened and read on <time datetime="2026-11-11">/, `${t.slug} dated note`);
  }
  assert.equal(twin.sources.official_pages_opened, twin.sources.list.filter((s) => s.kind !== 'copy').length);
  for (const s of twin.sources.list.filter((x) => x.kind === 'official')) assert.match(new URL(s.url).hostname, /\.gov$|\.org$/, s.url);
});

test('the hub strip has one stop per town in order, and a text list of the same towns', () => {
  const stops = [...hub.matchAll(/<a class="stop[^"]*" href="\/coast-commons\/([a-z-]+)\/"/g)].map((m) => m[1]);
  assert.deepEqual(stops, slugs);
  const list = [...hub.slice(hub.indexOf('id="towns"')).matchAll(/<li data-miles="[\d.]+" data-stay="[a-z]+"><a href="\/coast-commons\/([a-z-]+)\/"/g)].map((m) => m[1]);
  assert.deepEqual(list, slugs);
  assert.match(hub, /<svg class="strip"[^>]+role="img"/);
});

test('the plain box and the not-an-offer line are where they should be', () => {
  const pattern = page('pattern');
  for (const line of ['This is a study and a public resource. It is not an offer.', 'Nothing is being bought or sold. No money is being raised.', 'It is not legal, tax or investment advice.', 'Tradable shares in property are likely securities.', 'securities lawyer']) assert.ok(pattern.includes(line), line);
  for (const slug of ['', ...slugs]) assert.match(html(slug), /not an offer/i, `${slug || 'hub'} says it is not an offer`);
  assert.equal(twin.notice.length, 4);
});

test('the pattern keeps six ingredients and the other kinds of commons', () => {
  const pattern = page('pattern');
  assert.equal((pattern.match(/<ol class="six">[\s\S]*?<\/ol>/)[0].match(/<li>/g) || []).length, 6);
  for (const k of twin.pattern) assert.ok(pattern.toLowerCase().includes(k.toLowerCase().replace(', not ownership', '')), k);
  for (const k of ['Workshop', 'Community kitchen', 'Music room', 'Garden', 'Board library', 'Boat']) assert.ok(pattern.includes(`<b>${k}.</b>`), k);
  assert.match(pattern, /placeholder="your number"/, 'the calculator starts empty');
});

test('the flagship has the recipe, the city pages and a six-step ladder kept with try/catch', () => {
  const es = page('el-segundo');
  assert.equal((es.match(/data-step="\d"/g) || []).length, 6);
  for (const k of ['The first ten people', 'A rented weekend first', 'House rules', 'Open books', 'Use-rights, not ownership', 'A public-good share']) assert.ok(es.includes(`<dt>${k}</dt>`), k);
  assert.match(es, /try\{a=JSON\.parse\(localStorage\.getItem\(KEY\)/);
  assert.match(es, /try\{localStorage\.setItem\(KEY/);
  assert.match(es, /There is no house, no listing and no fund/);
  assert.ok(es.includes('https://www.elsegundo.gov/government/departments/community-development/short-term-home-sharing-rental-permit-pilot-program'));
});

test('every page is self-contained: no outside requests, canonical set', () => {
  for (const slug of all) {
    const h = html(slug);
    assert.ok(h.includes(`<link rel="canonical" href="https://pointcast.xyz/coast-commons/${slug ? `${slug}/` : ''}">`), `${slug || 'hub'} canonical`);
    assert.doesNotMatch(h, /<script[^>]+src=/i, `${slug || 'hub'} loads no script file`);
    assert.doesNotMatch(h, /<img\b|<iframe\b|@import|fetch\(|XMLHttpRequest|sendBeacon|WebSocket/, `${slug || 'hub'} makes no requests`);
    for (const m of h.matchAll(/<link[^>]+href="([^"]+)"/g)) assert.ok(m[1] === '/favicon.svg' || m[1].startsWith('/coast-commons') || m[1].startsWith('https://pointcast.xyz/coast-commons'), `${slug || 'hub'} link ${m[1]}`);
  }
  assert.doesNotMatch(read('public/coast-commons/cc.css'), /url\(|@import/);
});

test('content rules: nothing the area promised to leave out', () => {
  const banned = /good ?feels|cannabis|\bhemp\b|\bthc\b|zillow|redfin|\bmls\b|airbnb|vrbo|for sale by|buy now|invest now|guaranteed|\breturns?\b on|\broi\b/i;
  for (const slug of all) {
    const hit = html(slug).match(banned);
    assert.equal(hit, null, `${slug || 'hub'}: ${hit && hit[0]}`);
  }
  assert.equal(JSON.stringify(twin).match(banned), null);
  assert.equal(twin.licence.status, 'chosen');
  assert.equal(twin.licence.spdx, 'CC-BY-4.0');
  assert.ok(existsSync(new URL('public/coast-commons/LICENSE.txt', root)), 'licence note');
  assert.ok(existsSync(new URL('public/coast-commons/LICENSE-CC-BY-4.0.txt', root)), 'full licence text');
});

test('the area is registered: manifest, sitemap, new-today, llms and a sourced block', () => {
  const surfaces = read('src/data/agent-surfaces.ts');
  assert.ok(surfaces.includes("coastCommons: 'https://pointcast.xyz/coast-commons/'"));
  assert.ok(surfaces.includes("coastCommons: 'https://pointcast.xyz/coast-commons.json'"));
  const sitemap = read('src/pages/sitemap-discovery.xml.ts');
  for (const slug of ['pattern', ...slugs]) assert.ok(sitemap.includes(`'https://pointcast.xyz/coast-commons/${slug}/'`), slug);
  assert.ok(read('public/llms.txt').includes('https://pointcast.xyz/coast-commons/'));
  assert.ok(read('public/llms-full.txt').includes('https://pointcast.xyz/coast-commons.json'));
  const block = JSON.parse(read('src/content/blocks/0785.json'));
  assert.equal(block.author, 'cc');
  assert.ok(block.source && block.source.includes('November 11, 2026'));
  assert.equal(block.external.url, 'https://pointcast.xyz/coast-commons/');
  assert.equal(twin.block, 'https://pointcast.xyz/b/0785');
});
